    private static BigInteger shiftLeft(BigInteger u, long v) {
        if (v < 0) {
            if (v >= -Integer.MAX_VALUE) return u.shiftRight((int) -v);
            return (u.signum() < 0) ? BigInteger.ONE.negate() : BigInteger.ZERO;
